<script>
document.getElementById('add-criterion')?.addEventListener('click', () => {
    const list = document.getElementById('criteria-list');
    const index = list.querySelectorAll('.criterion-row').length;
    if (index >= 30) return;
    const row = document.createElement('div');
    row.className = 'border rounded p-3 criterion-row';
    row.innerHTML = `<div class="row g-2"><div class="col-lg-3"><label class="form-label">Nama kriteria</label><input name="criteria[${index}][nama]" maxlength="150" class="form-control" required></div><div class="col-lg-4"><label class="form-label">Deskripsi / indikator</label><input name="criteria[${index}][deskripsi]" class="form-control"></div><div class="col-lg-2"><label class="form-label">Bobot %</label><input name="criteria[${index}][bobot]" type="number" min="0.01" max="100" step="0.01" class="form-control" required></div><div class="col-lg-2"><label class="form-label">Skor maksimum</label><input name="criteria[${index}][skor_maksimum]" type="number" min="0.01" step="0.01" class="form-control" required></div><div class="col-lg-1 d-flex align-items-end"><span class="text-secondary small">${index + 1}</span></div></div>`;
    list.appendChild(row);
});
</script>
